:host{display:block;position:relative;height:calc(var(--screen-h, 900px) - 162px);min-height:620px;font-family:var(--sans);color:var(--ink)}*{box-sizing:border-box}
:host{
  --bg:#F6F4EF;--card:#FFFFFF;--ink:#1B1B18;--ink2:#3D3A33;--mut:#5E5B53;--mut2:#8E8A80;--line:#E3DFD5;--line2:#EFEBE3;--soft:#ECE8DF;
  --gold:#D9B46A;--gold2:#9A6614;--goldsoft:#FBF6EC;
  --green:#2E7D4F;--greent:#1E5E38;--greens:#E6F2EA;
  --amber:#B45309;--ambert:#8A3F06;--ambers:#FDF1E3;
  --red:#B42318;--redt:#9B1C12;--reds:#FDECEA;
  --sans:'IBM Plex Sans',system-ui,-apple-system,'Segoe UI',sans-serif;--mono:'IBM Plex Mono',ui-monospace,Menlo,monospace;--serif:Fraunces,Georgia,serif;
}











/* main */
.sv{position:relative;height:100%;display:grid;grid-template-rows:minmax(0,1fr) minmax(0,1fr);gap:14px}
.top{position:absolute;right:40px;top:-82px;height:54px;display:flex;align-items:center;gap:14px}
.ttl{display:flex;flex-direction:column;gap:2px;min-width:0}
.ttl .ey{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--mut)}
.ttl h1{margin:0;font-family:var(--serif);font-weight:500;font-size:26px;line-height:1.1;white-space:nowrap}
.seg{display:flex;gap:3px;padding:4px;background:var(--soft);border-radius:10px}
.seg button{border:0;background:transparent;font:inherit;font-size:13px;color:var(--ink2);padding:6px 11px;border-radius:7px;cursor:pointer;white-space:nowrap}
.seg button.on{background:var(--ink);color:#fff;font-weight:600}
.sp{flex:1}
.verdict{display:flex;align-items:center;gap:10px;padding:6px 14px 6px 6px;border-radius:12px;background:var(--card);border:1px solid var(--line)}
.vbadge{font-family:var(--mono);font-weight:600;font-size:13px;padding:6px 10px;border-radius:8px;letter-spacing:.04em}
.vbadge.fail{background:var(--reds);color:var(--redt)}.vbadge.pass{background:var(--greens);color:var(--greent)}
.verdict .vt{font-size:12px;line-height:1.35;color:var(--ink2)}.verdict .vt b{color:var(--ink)}
.kr{display:flex;flex-direction:column;gap:5px;padding:8px 12px;border-radius:10px;background:var(--ink);color:#F6F4EF}
.kr .v{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kr .l{display:flex;justify-content:space-between;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#C9C4B7}
.kr .l b{letter-spacing:0;text-transform:none;font-size:12px;color:var(--gold)}
.kr .v{font-size:13px}.kr .v strong{font-family:var(--mono)}
.krbar{position:relative;height:6px;border-radius:3px;background:#34322C}.krbar i{position:absolute;left:0;top:0;bottom:0;border-radius:3px;background:var(--gold)}.krbar u{position:absolute;top:-3px;width:2px;height:12px;background:#F6F4EF}
/* rows */
.row{display:grid;gap:14px;min-height:0}
.rA{grid-template-columns:minmax(0,7fr) minmax(0,5fr)}
.rB{grid-template-columns:minmax(0,4.6fr) minmax(0,3.5fr) minmax(0,3.9fr)}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px 18px;display:flex;flex-direction:column;min-height:0;min-width:0;position:relative}
.ch{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:6px}
.ch h2{margin:0;font-family:var(--serif);font-weight:500;font-size:19px;white-space:nowrap}
.ch .q{font-size:12px;color:var(--mut);text-align:right}
.ey{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--mut)}
svg{display:block;overflow:visible}
svg text{font-family:var(--sans)}
.num{font-family:var(--mono)}
/* unit economics */
.ue{flex:1;min-height:0;display:grid;grid-template-rows:repeat(3,minmax(0,1fr));gap:10px}
.uer{display:grid;grid-template-columns:150px minmax(0,1fr);gap:16px;align-items:stretch;min-height:0;padding:10px 12px;border-radius:12px;background:linear-gradient(180deg,var(--goldsoft),#fff 70%);border:1px solid var(--line2)}
.uel{display:flex;flex-direction:column;justify-content:center;gap:3px;min-width:0}
.uel .n{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut);white-space:nowrap}
.uel .v{font-family:var(--mono);font-size:24px;font-weight:600;line-height:1.1;color:var(--ink)}
.uel .d{align-self:flex-start;font-family:var(--mono);font-size:11px;font-weight:600;padding:2px 7px;border-radius:999px}
.uel .d.g{background:var(--greens)}.uel .d.a{background:var(--ambers)}.uel .d.r{background:var(--reds)}
.uel small{font-size:11px;color:var(--mut2)}
.uec{min-width:0;min-height:0;position:relative}
/* team */
.team{display:flex;flex-direction:column;flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain}
.th,.tr{display:grid;grid-template-columns:150px minmax(0,1fr) 62px 62px;gap:12px;align-items:center}
.colv{font-weight:600;color:var(--ink)}
.colrow{display:flex;gap:18px;flex-wrap:wrap;align-items:baseline;font-size:11.5px;color:var(--mut);padding:6px 4px 0;border-top:1px solid var(--line2)}.colrow b{font-family:'IBM Plex Mono';font-size:14px;color:var(--ink);font-weight:600;margin-left:4px}
.th{font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2);padding:0 0 6px;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:1;background:#FFFFFF}
.th span:nth-child(n+3){text-align:right}
.tr{flex:0 0 56px;border:0;border-bottom:1px solid var(--line2);background:transparent;font:inherit;color:inherit;text-align:left;cursor:pointer;padding:0;min-height:0;border-radius:6px}
.tr:hover{background:var(--goldsoft)}
.who{display:flex;align-items:center;gap:8px;min-width:0}.who i{width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-style:normal;font-size:10px;font-weight:700;color:#fff;flex-shrink:0}
.who div{min-width:0}.who b{display:block;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.who small{display:block;font-size:11px;color:var(--mut)}
.cbar{position:relative;height:18px}.cbar i{position:absolute;left:0;top:3px;height:12px;border-radius:3px;background:var(--ink)}.cbar span{position:absolute;top:1px;font-family:var(--mono);font-size:12px;font-weight:600;white-space:nowrap}
.cbar small{position:absolute;top:19px;left:0;font-size:10px;color:var(--mut);white-space:nowrap}
.pct{font-family:var(--mono);font-size:12px;font-weight:600;text-align:right;padding:3px 0;border-radius:6px}
.g{color:var(--greent)}.a{color:var(--ambert)}.r{color:var(--redt)}
.pg{background:var(--greens)}.pa{background:var(--ambers)}.pr{background:var(--reds)}
/* pipeline */
.pipe{display:flex;flex-direction:column;gap:8px;flex:1;min-height:0;justify-content:space-between}
.big{font-family:var(--serif);font-size:28px;line-height:1}
.mini{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.mini>div{background:var(--bg);border-radius:10px;padding:8px 10px;display:flex;flex-direction:column;gap:4px}
.mini .k{font-size:11px;color:var(--mut)}.mini .val{font-family:var(--mono);font-size:17px;font-weight:600}
.gbar{height:6px;border-radius:3px;background:var(--soft);position:relative}.gbar i{position:absolute;left:0;top:0;bottom:0;border-radius:3px}.gbar u{position:absolute;top:-3px;width:2px;height:12px;background:var(--ink)}
.mini .s{font-size:10.5px;color:var(--mut);line-height:1.3}
/* alerts */
.al{display:flex;flex-direction:column;flex:1;min-height:0}
.alr{display:grid;grid-template-columns:36px minmax(0,1fr) 110px;gap:10px;align-items:center;flex:0 1 60px;border-top:1px solid var(--line2);min-height:0}
.code{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--soft);border-radius:6px;padding:3px 0;text-align:center}
.alr .t{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.alr .o{font-size:11px;color:var(--mut);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ib{position:relative;height:16px}.ib i{position:absolute;right:0;top:3px;height:10px;border-radius:3px;background:var(--red);opacity:.85}.ib span{position:absolute;right:0;top:-12px;font-family:var(--mono);font-size:11px;font-weight:600}
.more{margin-top:auto;padding-top:8px;display:flex;justify-content:space-between;align-items:center;font-size:12px}
.lnk{border:0;background:none;padding:0;font:inherit;font-weight:600;color:var(--gold2);cursor:pointer}

