(function(R,TIP,TOAST){

/* ---- data: the same figures as the CRM LNP dashboard in LNP ---- */
let SALES=[
 {id:"lea",name:"Léa Moreau",ini:"LM",color:"#1B1B18",calls:26,won:8,close:34,cpc:1150,cash:24600,show:76},
 {id:"karim",name:"Karim Benali",ini:"KB",color:"#7A4B00",calls:24,won:8,close:33,cpc:1300,cash:27800,show:78},
 {id:"sofia",name:"Sofia Marchetti",ini:"SM",color:"#9A6614",calls:22,won:6,close:30,cpc:1230,cash:16000,show:72},
 {id:"ines",name:"Inès Fabre",ini:"IF",color:"#3D3A33",calls:20,won:9,close:39,cpc:1020,cash:25400,show:66},
 {id:"malik",name:"Malik Sy",ini:"MS",color:"#5E5B53",calls:18,won:7,close:31,cpc:1040,cash:18600,show:61}
];
const KPI={
 all:{sales:[38,38],cash:[112400,113000],cpc:[1050,1030],show:[70,71],refund:[4.3,4.4],aov:[3720,3660],funnel:[440,174,122,38],pond:70100,close:31.1,upfront:61,follow:73,velo:7}
};
let ALERTS=[
 {c:"1.5",o:"cro",imp:8400,t:"Écart signé / encaissé",obj:"Ventes de septembre"},
 {c:"2.4",o:"malik",imp:1450,t:"Vente qui stagne",obj:"Yassine Diallo · RDV pris"},
 {c:"2.3",o:"lea",imp:1180,t:"Relance manquante",obj:"M. Ferrand · 3 500 € · Appel honoré"},
 {c:"2.2",o:"karim",imp:900,t:"Message avant RDV manquant",obj:"Hugo Lemaire · RDV pris"},
 {c:"2.2",o:"lea",imp:820,t:"Message avant RDV manquant",obj:"Marc Dupont · RDV pris"},
 {c:"2.10",o:"lea",imp:720,t:"Prospect sans prochaine action",obj:"Nadia Benz · 6 000 € · Appel honoré"},
 {c:"2.10",o:"ines",imp:640,t:"Prospect sans prochaine action",obj:"Théo Laurent · 3 500 € · Appel honoré"},
 {c:"2.8",o:"sofia",imp:600,t:"Perte sans correctif",obj:"Hakim Touré · 6 000 € · Perdu"}
];
const PF={7:.24,30:1,56:1.85}, PL={7:"7 j",30:"30 j",56:"8 sem."};
const S={period:30};

let LIVE=null; const SALES0=SALES, ALERTS0=ALERTS, PAL=["#1B1B18","#7A4B00","#9A6614","#3D3A33","#5E5B53"];
// a rate with nothing to divide is not measured (NaN, shown "—"); cash and amounts are not measured until the CRM has payments / deals
const rt=(x,y)=>Number(y)?Number(x)/Number(y):NaN;
function liveFig(o){const P=LIVE.has_payments,D=LIVE.has_deals;return {sales:+o.won,cash:P?+o.cash:NaN,cpc:P?rt(o.cash,o.held):NaN,show:(o.shown_leads!=null?rt(o.shown_leads,+o.shown_leads+ +o.no_show_leads):rt(o.held,+o.held+ +o.no_show))*100,
  refund:P?rt(o.refunded,o.received)*100:NaN,aov:D?rt(o.signed,o.deals):NaN}}
function liveK(p){const n=LIVE.periods[p].now,a=liveFig(n),z=liveFig(LIVE.periods[p].base);
  return {sales:[a.sales,z.sales],cash:[a.cash,z.cash],cpc:[a.cpc,z.cpc],show:[a.show,z.show],refund:[a.refund,z.refund],aov:[a.aov,z.aov],
    signed:LIVE.has_deals?+n.signed:NaN,collected:LIVE.has_deals?+(n.collected||0):NaN,
    funnel:[+n.leads,+n.booked,+n.held,+n.won],pond:+LIVE.pipeline,close:rt(n.won,n.held)*100,upfront:LIVE.has_payments&&+n.signed?rt(n.cash,n.signed)*100:NaN,
    follow:rt(n.follow_done,n.follow_total)*100,velo:n.days_per_stage==null?NaN:+n.days_per_stage,noOutcome:+n.no_outcome||0}}
function liveTeam(p){return LIVE.team[p].map((t,i)=>{const f=t.figures,nm=t.name&&t.name!=="Unassigned"?t.name:"Non attribué";return {id:t.id,name:nm,ini:nm.split(/\s+/).map(w=>w[0]||"").join("").slice(0,2).toUpperCase(),
  color:PAL[i%PAL.length],calls:+f.held,won:+f.won,close:rt(f.won,f.held)*100,cpc:LIVE.has_payments?rt(f.cash,f.held):NaN,cash:LIVE.has_payments?+f.cash:0,signed:+(f.signed||0),collected:+(f.collected||0),show:(f.shown_leads!=null?rt(f.shown_leads,+f.shown_leads+ +f.no_show_leads):rt(f.held,+f.held+ +f.no_show))*100,booked:+f.booked}})
  .filter(s=>s.calls||s.won||s.cash||s.booked)}
// the few English words the SQL adds to the live alerts (overdue next move, stage name), shown in French
const STG={Show:"Présence",Decision:"Décision",Cash:"Encaissement",Won:"Gagné",Lost:"Perdu"};
const frTxt=t=>String(t==null?"":t).replace(/ · overdue$/," · en retard").replace(/ · (Show|Decision|Cash|Won|Lost)$/,(m,x)=>" · "+STG[x]);
function liveWeekly(k){return LIVE.weekly.map(w=>{const v=k==="cpc"?rt(w.cash,w.held):k==="aov"?rt(w.signed,w.deals):rt(w.refunded,w.received)*100;return isFinite(v)?v:0})}


/* ---- helpers ---- */
const nf=x=>!isFinite(x)?"—":Math.round(x).toLocaleString("fr-FR");
const money=x=>!isFinite(x)?"—":nf(x)+"\u00a0€";
const moneyK=x=>!isFinite(x)?"—":x>=1000?(Math.round(x/100)/10).toLocaleString("fr-FR")+"\u00a0k€":nf(x)+"\u00a0€";
const pc=(x,d=0)=>!isFinite(x)?"—":(Math.round(x*10**d)/10**d).toLocaleString("fr-FR",{minimumFractionDigits:d})+"\u00a0%";
const pl=x=>Math.round(x)>1?"s":""; // French plural: 0 and 1 are singular
const tone=(ratio)=>ratio>=100?"g":ratio>=95?"a":"r";
const COL={g:"var(--green)",a:"var(--amber)",r:"var(--red)"};
function series(end,base,seed){const o=[];for(let i=0;i<8;i++){const k=i/7;o.push(base*(1-k)+end*k+base*Math.sin((i+seed)*1.7)*.04)}o[7]=end;return o}
const el=(id)=>R.getElementById(id);
const tip=TIP;
function bindTips(root){root.querySelectorAll("[data-tip]").forEach(n=>{n.onmousemove=e=>{tip.innerHTML=n.getAttribute("data-tip");tip.style.opacity=1;tip.style.left=Math.min(innerWidth-270,e.clientX+14)+"px";tip.style.top=(e.clientY+14)+"px"};n.onmouseleave=()=>tip.style.opacity=0})}
function toast(m){const t=TOAST;t.textContent=m;t.style.opacity=1;clearTimeout(toast.h);toast.h=setTimeout(()=>t.style.opacity=0,2200)}

/* ---- controls ---- */
function controls(){
  el("per").innerHTML=[7,30,56].map(p=>`<button class="${S.period===p?"on":""}" data-p="${p}">${PL[p]}</button>`).join("");
  el("per").querySelectorAll("button").forEach(b=>b.onclick=()=>{S.period=+b.dataset.p;render()});
}

/* ---- the 6 parity criteria, computed once ---- */
function criteria(K,f){
  const d=[
    {k:"sales",l:"Ventes gagnées",v:K.sales[0]*f,b:K.sales[1]*f,fmt:nf},
    {k:"cash",l:"Montant encaissé",v:K.cash[0]*f,b:K.cash[1]*f,fmt:moneyK},
    {k:"show",l:"Taux de présence",v:K.show[0],b:K.show[1],fmt:x=>pc(x)},
    {k:"cpc",l:"Chiffre d’affaires par appel",v:K.cpc[0],b:K.cpc[1],fmt:money},
    {k:"aov",l:"Panier moyen",v:K.aov[0],b:K.aov[1],fmt:money},
    {k:"refund",l:"Taux de remboursement",v:K.refund[0],b:K.refund[1],fmt:x=>pc(x,1),inv:true}
  ];
  d.forEach(x=>{x.nd=!isFinite(x.v)||!isFinite(x.b)||(!x.b&&!x.v);x.ratio=x.nd?NaN:x.inv?(x.v?x.b/x.v*100:100):(x.b?x.v/x.b*100:100);x.tone=x.nd?"a":tone(x.ratio)});
  return Object.fromEntries(d.map(x=>[x.k,x]));
}

/* ---- header: parity verdict + LNP key result ---- */
function header(C){
  const below=Object.values(C).filter(x=>x.ratio<100), nd=Object.values(C).filter(x=>x.nd);
  const fail=below.length>0;
  el("verdict").innerHTML=`<span class="vbadge ${fail?"fail":nd.length?"":"pass"}"${!fail&&nd.length?' style="background:#ECE8DF;color:#5E5B53"':""}>${fail?"ÉCHEC":nd.length?"EN ATTENTE":"VALIDÉ"}</span><span class="vt"><b>Contrôle de parité</b><br>${fail?below.length+" sur 6 sous la référence":nd.length?(6-nd.length)+" sur 6 à la référence · "+nd.length+(nd.length>1?" non mesurés":" non mesuré"):"6 sur 6 à la référence"}</span>`;
  el("verdict").setAttribute("data-tip","Contrôle de parité : les 6 critères face à leur référence. "+(fail?"Sous la référence : "+below.map(x=>x.l.toLowerCase()).join(", ")+". ":"")+(nd.length?"Pas encore mesuré : "+nd.map(x=>x.l.toLowerCase()).join(", ")+" (pas encore de données dans le CRM). ":"")+"Ventes gagnées, taux de présence et montant encaissé sont marqués dans le flux, les trois autres dans la rentabilité unitaire.");

}

/* ---- 1. From lead to cash: one flow that carries volumes, conversion rates, deals won and cash ---- */
function flow(K,f,C){
  const box=el("flow"), W=box.clientWidth, H=box.clientHeight-30;
  if(W<200||H<120)return;
  const fn=K.funnel.map(x=>x*f), cash=K.cash[0]*f, signed=cash/(K.upfront/100);
  // signed, collected to date and still to collect on the sales of the period (Romain 2026-11-04)
  const sg=K.signed!=null?K.signed*f:signed, co=K.collected!=null?K.collected*f:signed*.7, re=sg-co;
  const st=[
    {l:"Prospects",v:fn[0],fmt:nf(fn[0])},
    {l:"RDV pris",v:fn[1],fmt:nf(fn[1])},
    {l:"Appels honorés",v:fn[2],fmt:nf(fn[2])},
    {l:"Ventes gagnées",v:fn[3],fmt:nf(fn[3]),crit:C.sales},
    {l:"Encaissé",v:fn[3],fmt:moneyK(cash),crit:C.cash,cash:true}
  ];
  const rates=[
    {v:fn[1]/fn[0]*100,l:"prise RDV",t:"Prise de RDV"},
    {v:LIVE?K.show[0]:fn[2]/fn[1]*100,l:"présence",t:"Taux de présence",crit:C.show},
    {v:LIVE?K.close:fn[3]/fn[2]*100,l:"conversion",t:"Taux de conversion"},
    {v:K.upfront,l:"comptant",up:true}
  ];
  const top=34, bot=78, hMax=H-top-bot, colW=Math.min(92,(W-40)/9), pad=22, gap=(W-2*pad-colW*5)/4;
  const hOf=v=>Math.max(10,hMax*Math.sqrt(Math.min(1,v/(Math.max(...fn)||1))));
  const mid=top+hMax/2;
  let s=`<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Du prospect à l’encaissement">`;
  s+=`<defs><linearGradient id="rib" x1="0" x2="1"><stop offset="0" stop-color="#ECE8DF"/><stop offset="1" stop-color="#F6F4EF"/></linearGradient></defs>`;
  // ribbons
  st.forEach((x,i)=>{if(i===4)return;const h1=hOf(x.v),h2=hOf(st[i+1].v),x1=pad+i*(colW+gap)+colW,x2=pad+(i+1)*(colW+gap);
    s+=`<path d="M${x1},${mid-h1/2} C${x1+gap/2},${mid-h1/2} ${x2-gap/2},${mid-h2/2} ${x2},${mid-h2/2} L${x2},${mid+h2/2} C${x2-gap/2},${mid+h2/2} ${x1+gap/2},${mid+h1/2} ${x1},${mid+h1/2}Z" fill="url(#rib)"/>`;
    const r=rates[i], rc=r.crit?COL[r.crit.tone]:"var(--ink)";
    const cx=(x1+x2)/2;
    const lbl=r.crit?`${pc(r.v)}`:pc(r.v);
    const tipTxt=r.crit?`${r.t} : ${pc(r.v)} · référence ${pc(r.crit.b)} (${pc(r.crit.ratio)} de la référence)`:r.up?`Part du chiffre d’affaires signé payée à la signature : ${pc(r.v)}. Le reste, ce sont des échéances encore à encaisser.`:`${r.t} : ${pc(r.v)}`;
    s+=`<g data-tip="${tipTxt}"><rect x="${cx-38}" y="${mid-19}" width="76" height="38" rx="9" fill="#fff" stroke="${r.crit?rc:"#E3DFD5"}" stroke-width="${r.crit&&r.crit.tone!=="g"?1.5:1}"/>
      <text x="${cx}" y="${mid+1}" text-anchor="middle" font-family="IBM Plex Mono" font-size="15" font-weight="600" fill="${rc}">${lbl}</text>
      <text x="${cx}" y="${mid+13}" text-anchor="middle" font-size="10" fill="#5E5B53">${r.l}</text></g>`;
  });
  // columns
  st.forEach((x,i)=>{
    const h=hOf(x.v), x0=pad+i*(colW+gap), y0=mid-h/2, c=x.crit?COL[x.crit.tone]:null;
    if(x.cash){
      const hc=h*((isFinite(K.upfront)?K.upfront:0)/100);
      s+=`<g data-tip="Chiffre d’affaires signé ${moneyK(signed)} · encaissé ${moneyK(cash)} (${pc(K.upfront)} à la signature) · référence ${moneyK(x.crit.b)}"><rect x="${x0}" y="${y0}" width="${colW}" height="${h}" rx="6" fill="#FBF6EC" stroke="#D9B46A" stroke-dasharray="3 3"/>
        <rect x="${x0}" y="${y0+h-hc}" width="${colW}" height="${hc}" rx="6" fill="#D9B46A"/></g>`;
    } else s+=`<rect x="${x0}" y="${y0}" width="${colW}" height="${h}" rx="6" fill="${i===3?"#1B1B18":"#3D3A33"}" opacity="${i===3?1:.9-i*.12}"/>`;
    // labels
    s+=`<text x="${x0+colW/2}" y="${top-16}" text-anchor="middle" font-size="11" font-weight="600" letter-spacing=".06em" fill="#5E5B53">${x.l.toUpperCase()}</text>`;
    const vy=H-bot+26;
    s+=`<text x="${x0+colW/2}" y="${vy}" text-anchor="middle" font-family="Fraunces" font-size="${x.cash?24:22}" fill="#1B1B18">${x.fmt}</text>`;
    if(x.crit){
      s+=`<g data-tip="${x.crit.l} : ${x.crit.fmt(x.crit.v)} · référence ${x.crit.fmt(x.crit.b)}"><rect x="${x0+colW/2-56}" y="${vy+10}" width="112" height="20" rx="10" fill="${x.crit.tone==="g"?"#E6F2EA":x.crit.tone==="a"?"#FDF1E3":"#FDECEA"}"/>
      <text x="${x0+colW/2}" y="${vy+24}" text-anchor="middle" font-family="IBM Plex Mono" font-size="11" font-weight="600" fill="${x.crit.tone==="g"?"#1E5E38":x.crit.tone==="a"?"#8A3F06":"#9B1C12"}">${x.crit.nd?"non mesuré":pc(x.crit.ratio)+" de la réf."}</text></g>`;
    } else if(x.cash===undefined && i<3){
      s+=`<text x="${x0+colW/2}" y="${vy+22}" text-anchor="middle" font-size="11" fill="#8E8A80">${i===0?"entrés":i===1?"à l’agenda":(LIVE&&K.noOutcome?"réalisés · "+nf(K.noOutcome)+" sans issue":"réalisés")}</text>`;
