  s+=`</svg>`;
  s+=`<div class="colrow" data-tip="Sur les ventes de la période : le chiffre d’affaires signé (prix de l’offre), ce qui a déjà été collecté à ce jour (échéances arrivées, estimé d’après l’échéancier tant que les paiements ne sont pas enregistrés) et ce qui reste à collecter."><span>CA signé<b>${moneyK(sg)}</b></span><span>CA collecté<b>${moneyK(co)}</b> <span class="num">(${pc(sg?co/sg*100:NaN)})</span></span><span>Reste à collecter<b>${moneyK(re)}</b></span></div>`;
  box.innerHTML=s; bindTips(box);
  el("flowq").textContent=`${PL[S.period]} · réf. = les ${PL[S.period]} d’avant · ${LIVE?"CRM en direct":"exemple"}`;
