/* ---- 2. Unit economics: the 3 remaining parity criteria, each as a full-size 8-week area chart against its baseline ---- */
function smooth(pts){let d="M"+pts[0][0]+","+pts[0][1];for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;
  d+=` C${(p1[0]+(p2[0]-p0[0])/6).toFixed(1)},${(p1[1]+(p2[1]-p0[1])/6).toFixed(1)} ${(p2[0]-(p3[0]-p1[0])/6).toFixed(1)},${(p2[1]-(p3[1]-p1[1])/6).toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`}return d}
function unit(C){
  const L=[C.cpc,C.aov,C.refund];
  el("ue").innerHTML=L.map((x,i)=>{const dv=(x.ratio-100), sg=dv>=0?"+":"−";
    return `<div class="uer"><div class="uel"><span class="n">${x.l}</span><span class="v">${x.fmt(x.v)}</span>
      <span class="d ${x.tone}" data-tip="${x.inv?"Plus c’est bas, mieux c’est. ":""}${pc(x.ratio)} de la référence">${x.nd?"non mesuré":sg+pc(Math.abs(dv))+" vs réf."}</span><small>réf. ${x.fmt(x.b)}${x.inv?" · plus bas = mieux":""}</small></div>
      <div class="uec" id="uec${i}"></div></div>`}).join("");
  L.forEach((x,i)=>{
    const box=el("uec"+i), W=box.clientWidth, H=box.clientHeight; if(W<80||H<40) return;
    if(x.nd){box.innerHTML=`<p style="margin:14px 0 0;font-size:12px;color:var(--mut)">Pas encore mesuré : ${i===1?"aucune vente avec un montant":"aucun paiement"} dans le CRM.</p>`;return}
    const ser=LIVE?liveWeekly(["cpc","aov","refund"][i]):series(x.v,x.b,i+2), mn=Math.min(...ser,x.b), mx=Math.max(...ser,x.b), pad=(mx-mn)*.25||1;
    const lo=mn-pad, hi=mx+pad, T=8, B=16, R=54;
    const X=j=>j/7*(W-R), Y=v=>T+(1-(v-lo)/(hi-lo))*(H-T-B);
    const pts=ser.map((v,j)=>[X(j),Y(v)]), line=smooth(pts), last=pts[7], yb=Y(x.b);
    // worse than baseline = red: under it, or over it when lower is better
    const G="var(--green)", Rd="var(--red)", cUp=x.inv?Rd:G, cDn=x.inv?G:Rd, cEnd=(x.inv?x.v>x.b:x.v<x.b)?Rd:G;
    let s=`<svg width="${W}" height="${H}" role="img" aria-label="${x.l}, 8 dernières semaines"><defs>
      <clipPath id="uu${i}"><rect x="-10" y="-10" width="${W+20}" height="${yb+10}"/></clipPath>
      <clipPath id="ud${i}"><rect x="-10" y="${yb}" width="${W+20}" height="${H}"/></clipPath>
      <linearGradient id="gu${i}" gradientUnits="userSpaceOnUse" x1="0" y1="${T}" x2="0" y2="${yb}"><stop offset="0" style="stop-color:${cUp};stop-opacity:.05"/><stop offset="1" style="stop-color:${cUp};stop-opacity:.3"/></linearGradient>
      <linearGradient id="gd${i}" gradientUnits="userSpaceOnUse" x1="0" y1="${yb}" x2="0" y2="${H-B}"><stop offset="0" style="stop-color:${cDn};stop-opacity:.3"/><stop offset="1" style="stop-color:${cDn};stop-opacity:.05"/></linearGradient></defs>`;
    const band=`${line} L${last[0]},${yb} L0,${yb} Z`;
    s+=`<path d="${band}" fill="url(#gu${i})" clip-path="url(#uu${i})"/><path d="${band}" fill="url(#gd${i})" clip-path="url(#ud${i})"/>`;
    s+=`<line x1="0" x2="${W-R}" y1="${yb}" y2="${yb}" stroke="var(--mut2)" stroke-dasharray="4 4"/><text x="${W-R+6}" y="${yb+4}" font-size="10" fill="var(--mut2)">réf.</text>`;
    s+=`<path d="${line}" fill="none" stroke="${cUp}" stroke-width="2.5" stroke-linecap="round" clip-path="url(#uu${i})"/><path d="${line}" fill="none" stroke="${cDn}" stroke-width="2.5" stroke-linecap="round" clip-path="url(#ud${i})"/>`;
    s+=`<circle cx="${last[0]}" cy="${last[1]}" r="9" fill="${cEnd}" opacity=".15"/><circle cx="${last[0]}" cy="${last[1]}" r="4.5" fill="#fff" stroke="${cEnd}" stroke-width="2.5"/>`;
    s+=`<text x="0" y="${H-3}" font-size="10" fill="var(--mut2)">il y a 8 sem.</text><text x="${W-R}" y="${H-3}" font-size="10" text-anchor="end" fill="var(--mut2)">maintenant</text>`;
    ser.forEach((v,j)=>s+=`<rect x="${X(j)-(W-R)/14}" y="0" width="${(W-R)/7}" height="${H}" fill="transparent" data-tip="${j===7?"Cette semaine":"Il y a "+(7-j)+" sem."} : ${x.fmt(v)}"/>`);
    box.innerHTML=s+`</svg>`;
  });
  bindTips(el("ue"));
}

/* ---- 3. Team: cash as the bar, close and show rates as the two quality checks ---- */
function team(f){
  const t=SALES.slice().sort((a,b)=>b.cash-a.cash);
  const mx=Math.max(1,...t.map(s=>s.cash));
  if(!t.length){el("team").innerHTML=`<p style="color:var(--mut);font-size:13px;margin:8px 0">Aucune activité commerciale sur cette période.</p>`;return}
  el("team").innerHTML=`<div class="th"><span>Commercial</span><span data-tip="Montant encaissé · ventes gagnées / appels · collecté à ce jour / signé, sur les ventes de la période">Encaissé · collecté / signé</span><span data-tip="Taux de conversion">Conversion</span><span data-tip="Taux de présence">Présence</span></div>`+
   t.map(s=>{const w=s.cash/mx*100, cl=s.close>=32?"g":s.close>=28?"a":"r", sh=s.show>=72?"g":s.show>=65?"a":"r";
    return `<button class="tr" data-id="${s.id}" data-tip="${s.name} : ${money(s.cash*f)} encaissés, ${nf(s.won*f)} vente${pl(s.won*f)} gagnée${pl(s.won*f)} sur ${nf(s.calls*f)} appel${pl(s.calls*f)}">
      <span class="who"><i style="background:${s.color}">${s.ini}</i><div><b>${s.name}</b><small>${money(s.cpc)} par appel</small></div></span>
      <span class="cbar"><i style="width:calc((100% - 62px) * ${w/100})"></i><span style="left:calc((100% - 62px) * ${w/100} + 6px)">${moneyK(s.cash*f)}</span><small>${nf(s.won*f)} gagnée${pl(s.won*f)} / ${nf(s.calls*f)} appel${pl(s.calls*f)} · <b class="colv" data-tip="${s.name} : ${money((s.collected!=null?s.collected:s.cash)*f)} collectés à ce jour sur ${money((s.signed!=null?s.signed:s.cash)*f)} signés">${moneyK((s.collected!=null?s.collected:s.cash)*f)} / ${moneyK((s.signed!=null?s.signed:s.cash)*f)}</b></small></span>
      <span class="pct ${cl} p${cl}">${pc(s.close)}</span><span class="pct ${sh} p${sh}">${pc(s.show)}</span>
    </button>`}).join("");
  el("team").querySelectorAll(".tr").forEach(b=>b.onclick=()=>window.postMessage({lnp:"crm",owner:b.dataset.id},"*"));
  bindTips(el("team"));
}

/* ---- 4. What's coming: weighted pipeline turned into a cash forecast, plus the two speed checks ---- */
function pipe(K){
  const fc=K.pond*K.upfront/100, w=K.pond?fc/K.pond*100:0;
  el("pipe").innerHTML=`
    <div data-tip="Pipeline pondéré : chaque vente en cours × la probabilité de gain observée à son étape. Prévision = pipeline pondéré × part observée payée à la signature.">
      <div class="ey" style="margin-bottom:4px">Prévision d’encaissement à 30 jours</div>
      <div style="display:flex;align-items:baseline;gap:8px"><span class="big">${moneyK(fc)}</span><span class="num" style="font-size:12px;color:var(--mut)">sur ${moneyK(K.pond)} pondérés</span></div>
      <div style="position:relative;height:16px;border-radius:5px;background:#FBF6EC;border:1px dashed #D9B46A;margin-top:8px"><i style="position:absolute;left:0;top:0;bottom:0;width:${w}%;border-radius:4px;background:var(--gold)"></i></div>
      <div style="display:flex;justify-content:space-between;font-size:10.5px;color:var(--mut);margin-top:4px"><span>encaissement attendu</span><span>reste en pipeline pondéré</span></div>
    </div>
    <div class="mini">
      <div data-tip="Ventes en cours relancées sous 24 h. Objectif 75 %."><span class="k">Relance sous 24 h</span><span class="val ${K.follow<75?"a":"g"}">${pc(K.follow)}</span><div class="gbar"><i style="width:${K.follow}%;background:${K.follow<75?"var(--amber)":"var(--green)"}"></i><u style="left:75%"></u></div><span class="s">objectif 75 %</span></div>
      <div data-tip="Nombre médian de jours qu’une vente passe à chaque étape. Alerte au-delà de 8 jours."><span class="k">Jours par étape</span><span class="val ${K.velo>8?"a":"g"}">${isFinite(K.velo)?String(K.velo).replace(".",",")+" j":"—"}</span><div class="gbar"><i style="width:${Math.min(100,K.velo/14*100)}%;background:${K.velo>8?"var(--amber)":"var(--green)"}"></i><u style="left:${8/14*100}%"></u></div><span class="s">alerte au-delà de 8 j</span></div>
    </div>
`;
  bindTips(el("pipe"));
}

/* ---- 5. Cash at risk: the alerts ranked by money at stake ---- */
function alerts(){
  const L=ALERTS.slice().sort((a,b)=>b.imp-a.imp);
  const tot=L.reduce((x,a)=>x+a.imp,0), mx=Math.max(...L.map(a=>a.imp),1), shown=L.slice(0,5);
  if(LIVE&&!L.length){el("alq").innerHTML="0 alerte";el("al").innerHTML=`<p style="color:var(--mut);font-size:13px;margin:8px 0">Rien à risque pour l’instant : aucune alerte ouverte et aucune prochaine étape en retard.</p>`;return}
  el("alq").innerHTML=`<b class="num" style="color:var(--redt);font-size:13px">~${moneyK(tot)}</b> · ${L.length} alerte${L.length>1?"s":""}`;
  el("al").innerHTML=shown.map(a=>{const s=SALES.find(x=>x.id===a.o);
    return `<div class="alr" data-tip="${a.t} · ${a.obj} · ${s?s.name:(LIVE?"Non attribué":"Direction")} · impact estimé ${money(a.imp)}"><span class="code">${a.c}</span><div style="min-width:0"><div class="t">${a.t}</div><div class="o">${a.obj} · ${s?s.name.split(" ")[0]:(LIVE?"Non attribué":"Direction")}</div></div>
    <div class="ib"><i style="width:${Math.max(6,a.imp/mx*100)}%"></i><span>~${moneyK(a.imp)}</span></div></div>`}).join("")+
    `<div class="more"><span style="color:var(--mut)">${L.length>5?(L.length-5)+" de plus, ~"+moneyK(L.slice(5).reduce((x,a)=>x+a.imp,0)):""}</span><button class="lnk" data-allalerts>Voir toutes les alertes →</button></div>`;
  bindTips(el("al"));
  const aa=el("al").querySelector("[data-allalerts]"); if(aa) aa.onclick=()=>window.postMessage({lnp:"crm",view:"alerts"},"*");
}

function cover(msg,retry){let c=R.getElementById("livecover");if(!msg){if(c)c.remove();return}
  if(!c){c=document.createElement("div");c.id="livecover";c.setAttribute("role","status");c.style.cssText="position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;gap:12px;background:var(--bg);font-size:14px;color:var(--mut)";R.querySelector(".sv").appendChild(c)}
  c.textContent=msg;if(retry){const b=document.createElement("button");b.textContent="Réessayer";b.style.cssText="font:inherit;font-weight:600;border:1px solid #D8D3C7;background:#fff;border-radius:10px;padding:8px 14px;cursor:pointer;color:var(--ink)";b.onclick=()=>{cover("Chargement des chiffres en direct…");loadLive()};c.appendChild(b)}}
function render(){
  const K=LIVE?liveK(S.period):KPI.all, f=LIVE?1:PF[S.period], C=criteria(K,f);
  SALES=LIVE?liveTeam(S.period):SALES0; ALERTS=LIVE?LIVE.alerts.map(a=>({c:a.c==="next"?"SLA":a.c,o:a.o,imp:+a.imp,t:frTxt(a.t),obj:frTxt(a.obj)})):ALERTS0;
  controls(); header(C); flow(K,f,C); unit(C); team(f); pipe(K); alerts(); bindTips(el("verdict").parentNode);
}


